import { eventKey } from "./idempotency.js";

// AC-2.2: track the open LHC turn; emit exactly one `turn_end` at `agent_end`;
// ignore PI's per-step `turn_end` as a boundary signal. Pure state machine.
//
// An LHC turn opens on a `user_prompt` and stays open across every agent step.
// The converter never feeds PI's per-step `turn_end` here, so it can never close
// a turn; only `onAgentEnd()` does, and only when a turn is open. A run that
// never reaches `agent_end` (hard kill) leaves the turn open — tolerated as a
// no-op on reattach, since a fresh accumulator has no open turn to close.

export interface TurnAccumulatorCtx {
  piSessionId: string;
  actor?: string;
  harness?: string;
  /** Seed for the turn counter, so a connector reattaching to an EXISTING
   *  thread continues past the prior session's turn_end keys instead of
   *  restarting at 0 and colliding with them (SV-001). Defaults to 0 — a fresh
   *  thread or a deterministic from-scratch replay starts here unchanged. */
  startTurnSeq?: number;
}

export class TurnAccumulator {
  private readonly piSessionId: string;
  private readonly actor: string;
  private readonly harness: string;
  private open = false;
  // A monotonic counter giving each emitted `turn_end` a distinct idempotency
  // key. Seeded from the thread's durable closed-turn count at attach so a
  // resume/reload continues past prior keys; within a from-scratch run (seed 0)
  // it stays replay-stable, so a deterministic re-replay re-derives and dedups.
  private closedCount: number;

  constructor(ctx: TurnAccumulatorCtx) {
    this.piSessionId = ctx.piSessionId;
    this.actor = ctx.actor ?? "system";
    this.harness = ctx.harness ?? "pi";
    this.closedCount = ctx.startTurnSeq ?? 0;
  }

  /** Open the turn when this message's events include a `user_prompt`. A new
   *  prompt mid-run is handled by LHC's own turn machine (close-then-open); the
   *  accumulator only needs to know a turn is open for the `agent_end` close. */
  onMessage(events: MessageEventInput[]): void {
    if (events.some((event) => event.eventKind === "user_prompt")) {
      this.open = true;
    }
  }

  /** Returns `[turn_end]` when a turn is open, else `[]`. Closing is the only
   *  transition the accumulator drives, and it happens once per agent run. */
  onAgentEnd(): MessageEventInput[] {
    if (!this.open) return [];
    this.open = false;
    const key = eventKey({
      piSessionId: this.piSessionId,
      entryId: `turn:${this.closedCount}`,
      blockIndex: 0,
      kind: "turn_end",
    });
    this.closedCount += 1;
    return [
      {
        eventKind: "turn_end",
        idempotencyKey: key,
        actor: this.actor,
        harness: this.harness,
        payload: {},
      },
    ];
  }

  hasOpenTurn(): boolean {
    return this.open;
  }
}
